import { isAriaProp } from "./isAriaProp";
/**
 * The complement of `getAriaAttributes`: every prop that is *not* an aria attribute, returned
 * under its original key and value.
 *
 * Use the two together when a component has to send its aria attributes to a different element
 * than the rest of its props. Both sides test membership with `isAriaProp`, so no prop can fall
 * between them and be dropped by both.
 */
export const getNonAriaProps = (props) => {
    if (!props) {
        return {};
    }
    return Object.fromEntries(Object.entries(props).filter(([key]) => !isAriaProp(key)));
};
