import { isAriaProp } from "./isAriaProp";
const camelToKebab = (str) => str.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`);
export const getAriaAttributes = (props) => {
    if (!props) {
        return {};
    }
    const ariaAttributes = {};
    for (const [key, value] of Object.entries(props)) {
        if (!isAriaProp(key)) {
            continue;
        }
        // Hyphenated keys (aria-*) pass through; camelCase keys (ariaDescribedby, ariaLabel, etc.)
        // are converted to the hyphenated form the DOM expects.
        ariaAttributes[key.startsWith("aria-") ? key : camelToKebab(key)] = value;
    }
    return ariaAttributes;
};
